input.newString:
func TestAdd(t *testing.T) {
	maxInt := int(^uint(0) >> 1)
	minInt := -maxInt - 1

	tests := []struct {
		name string
		a    int
		b    int
		want int
	}{
		{
			name: "small positive values",
			a:    2,
			b:    3,
			want: 5,
		},
		{
			name: "large positive values",
			a:    1_000_000,
			b:    2_000_000,
			want: 3_000_000,
		},
		{
			name: "large negative values",
			a:    -1_000_000,
			b:    -2_000_000,
			want: -3_000_000,
		},
		{
			name: "large values with mixed signs",
			a:    2_000_000,
			b:    -1_000_000,
			want: 1_000_000,
		},
		{
			name: "maximum integer",
			a:    maxInt,
			b:    0,
			want: maxInt,
		},
		{
			name: "minimum integer",
			a:    minInt,
			b:    0,
			want: minInt,
		},
		{
			name: "large values near half the maximum",
			a:    maxInt / 2,
			b:    maxInt / 2,
			want: (maxInt / 2) * 2,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := add(tt.a, tt.b)
			if got != tt.want {
				t.Fatalf("add(%d, %d) = %d, want %d", tt.a, tt.b, got, tt.want)
			}
		})
	}
}

